 93	\begin{lemma}[Projectivity of the single-basis marginals]\label{lem:s-w-marginals-projective}
 94		\lean{MIPStarRE.QPBT.GlobalPairWitness.marginalPoly_isProjective}
 95		\leanok
 96		\uses{def:s-w-marginals, lem:qld-4-7}
 97		For each $W\in\{X,Z\}$, the family $\{\hat{S}^W_g\}_g$ is a projective measurement with outcomes in $\mathrm{ideg}_{d,m}(\F_q)$.
 98	\end{lemma}
 99	\begin{proof}
100		\leanok
101		\uses{def:s-w-marginals, lem:sandwich-postprocess-projective}
102		By Definition~\ref{def:s-w-marginals}, each marginal is the finite postprocessing
103		of the joint projective measurement by the outcome map $(g_X,g_Z)\mapsto g_W$.
104		Lemma~\ref{lem:sandwich-postprocess-projective} shows that this postprocessing
105		preserves projectivity.
106	\end{proof}
