108	\begin{definition}[Pauli dot-product projectors]\label{def:tau-dot-product-projector}
109		\lean{MIPStarRE.QPBT.tauDotProj}
110		\leanok
111		\uses{def:generalized-pauli}
112		For $W \in \{X,Z\}$ and $h \in \F_q^{M}$ let $\tau^W_h$ denote the projector corresponding to measuring $(\C^q)^{\ot M}$ in the $W$ basis and obtaining the outcome $h$ (Definition~\ref{def:generalized-pauli}). For all $W \in \{X,Z\}$, $\tilde{u} \in \F_q^{M}$, and $a \in \F_q$, define the operator
113		\begin{equation}\label{eq:def-tauwu}
114			\tau^{W}_{a}(\tilde{u}) = \sum_{h \in \F_q^{M} \,:\, h \cdot \tilde{u} = a} \tau^W_{h}\;.
115		\end{equation}
116	\end{definition}
