118	\begin{lemma}[Projectivity and completeness of the dot-product operators]\label{lem:tau-dot-product-projective}
119		\lean{MIPStarRE.QPBT.tauDotProj_isProj, MIPStarRE.QPBT.sum_tauDotProj_eq_one}
120		\leanok
121		\uses{def:tau-dot-product-projector, def:generalized-pauli}
122		For each fixed $W$ and $\tilde{u}$, every $\tau^W_a(\tilde{u})$ is a projector and
123		$\sum_{a\in\F_q}\tau^W_a(\tilde{u})=\Id$. Thus
124		$\{\tau^W_a(\tilde{u})\}_{a\in\F_q}$ is a projective measurement.
125	\end{lemma}
