138	\begin{lemma}[Projectivity and completeness of the pulled-apart measurements]\label{lem:tilde-m-projective}
139		\lean{MIPStarRE.QPBT.tildeM_isProj, MIPStarRE.QPBT.sum_tildeM_eq_one}
140		\leanok
141		\uses{def:tilde-m-measurement, lem:s-w-marginals-projective,
142			lem:tau-dot-product-projective}
143		For each $W$ and $\tilde{u}$, every $\tilde{M}^{W,\tilde{u}}_a$ is a projector and
144		$\sum_{a\in\F_q}\tilde{M}^{W,\tilde{u}}_a=\Id$. Thus
145		$\{\tilde{M}^{W,\tilde{u}}_a\}_{a\in\F_q}$ is a projective measurement.
146	\end{lemma}
